// Input validation: never trust what an inbound workflow (or a webhook) hands you.
const input = $('When Called by Inbound').first().json;
const allowed = ['telegram', 'whatsapp', 'messenger', 'instagram', 'test'];
const errors = [];
const channel = String(input.channel || '').toLowerCase().trim();
const userId = String(input.channel_user_id || '').trim();
let text = String(input.text ?? '').replace(/\s+/g, ' ').trim();
const type = String(input.message_type || 'text').toLowerCase();
if (!allowed.includes(channel)) errors.push(`unknown channel "${channel}"`);
if (!userId) errors.push('missing channel_user_id');
if (!input.message_id) errors.push('missing message_id');
if (!text && type === 'text') errors.push('empty text');
if (errors.length) throw new Error('Invalid input: ' + errors.join('; '));
if (text.length > 2000) text = text.slice(0, 2000);
return [{ json: {
  customer_id: `${channel}:${userId}`,
  channel, channel_user_id: userId,
  message_id: String(input.message_id),
  text: text || `[${type} message]`,
  is_text: type === 'text' && text.length > 0,
  customer_name: String(input.customer_name || '').slice(0, 80),
  received_at: input.received_at || new Date().toISOString(),
}}];

// Merge the new message with what we already know: customer record + last N turns.
const cfg = $('Get Config').first().json;
const msg = $('Validate Input').first().json;
const found = $('Find Customer').all().map(i => i.json).find(r => r.customer_id === msg.customer_id);
const rows = $('Load History').all().map(i => i.json).filter(r => r.customer_id === msg.customer_id && r.text);
const turns = Number(cfg.HISTORY_TURNS) || 6;
const label = r => r.direction === 'in' ? 'Customer' : (r.sender === 'staff' ? 'Staff' : 'Assistant');
const history = rows.slice(-turns).map(r => `${label(r)}: ${String(r.text).slice(0, 300)}`).join('\n');
const now = DateTime.now().setZone(cfg.TIMEZONE);
return [{ json: {
  ...msg,
  is_new_customer: !found,
  stored_name: found?.name || '',
  stored_phone: found?.phone ? String(found.phone) : '',
  mode: found?.mode || 'ai',
  open_ticket_id: found?.open_ticket_id || '',
  first_seen: found?.first_seen || now.toISO(),
  message_count: (Number(found?.message_count) || 0) + 1,
  history: history || '(no previous messages)',
  today_text: now.toFormat('cccc, d LLLL yyyy, HH:mm'),
  today_date: now.toISODate(),
}}];

// Graceful degradation: if the AI is down or keeps returning bad JSON, classify with simple rules.
const ctx = $('Build Context').first().json;
const t = ctx.text;
const has = re => re.test(t);
let intent = 'other';
if (has(/(pain|hurts?|bleed|swell|swollen|broken tooth|knocked|وجع|يوجع|ألم|نزيف|ينزف|ورم|وارم|تورم|خراج|مكسور)/i)) intent = 'urgent';
else if (has(/(book|appointment|reserve|حجز|احجز|ميعاد|موعد)/i)) intent = 'booking';
else if (has(/(complain|rude|refund|worst|terrible|شكوى|زعلان|وحش|فلوسي)/i)) intent = 'complaint';
else if (has(/(human|agent|manager|doctor|staff|حد من|الدكتور|المدير|موظف)/i)) intent = 'human_request';
else if (has(/(price|cost|how much|hours|open|where|location|insurance|بكام|سعر|مواعيد|فين|عنوان|تأمين)/i)) intent = 'faq';
else if (has(/^(hi|hello|hey|thanks|thank you|السلام|اهلا|أهلا|مرحبا|شكرا)/i)) intent = 'greeting';
return [{ json: { output: {
  intent, language: /[؀-ۿ]/.test(t) ? 'ar' : 'en', sentiment: 'neutral',
  urgency: intent === 'urgent' ? 'high' : 'low', needs_human: ['urgent', 'human_request'].includes(intent),
  summary: t.slice(0, 120), search_query: t, booking: { name: '', phone: '', service: '', date: '', time: '' },
}, __fallback: true } }];

// AI output validation: enforce allowed values, apply safety rules, decide the route.
const ctx = $('Build Context').first().json;
const raw = $json.output || {};
const notes = [];
const pick = (v, allowed, dflt, field) => {
  const s = String(v ?? '').toLowerCase().trim();
  if (allowed.includes(s)) return s;
  notes.push(`${field} "${v}" replaced with "${dflt}"`);
  return dflt;
};
const isArabic = /[؀-ۿ]/.test(ctx.text);
let intent = pick(raw.intent, ['faq', 'booking', 'complaint', 'urgent', 'human_request', 'greeting', 'other'], 'other', 'intent');
let language = pick(raw.language, ['ar', 'en'], isArabic ? 'ar' : 'en', 'language');
if (isArabic && language !== 'ar') { language = 'ar'; notes.push('language corrected from script'); }
let sentiment = pick(raw.sentiment, ['positive', 'neutral', 'negative', 'angry'], 'neutral', 'sentiment');
let urgency = pick(raw.urgency, ['low', 'medium', 'high', 'critical'], 'low', 'urgency');

// Safety net: symptom words win over the model unless the message is a general question.
const symptoms = /(\b(pain|painful|hurts?|aching|toothache|bleed(ing)?|blood|swell(ing)?|swollen|abscess|knocked[- ]out|broken tooth|fever)\b|وجع|بيوجع|يوجعني|ألم|الألم|نزيف|بينزف|ينزف|وارم|ورم|تورم|منفوخ|خراج|مكسور|اتكسر|انكسر|سخونية)/i;
const generalQuestion = /\b(does|do|is|will|can|should|how|what)\b[^.!]*\?/i.test(ctx.text) || /(^|\s)هل\s/.test(ctx.text);
if (symptoms.test(ctx.text) && !generalQuestion && intent !== 'urgent') {
  notes.push(`safety rule: "${intent}" upgraded to urgent`);
  intent = 'urgent';
  if (!['high', 'critical'].includes(urgency)) urgency = 'high';
}

const needs_human = raw.needs_human === true || ['urgent', 'human_request'].includes(intent) || sentiment === 'angry';
let route = 'smalltalk';
if (needs_human) route = 'handoff';
else if (intent === 'complaint') route = 'complaint';
else if (intent === 'booking') route = 'booking';
else if (intent === 'faq') route = 'faq';
const ticket_type = intent === 'urgent' ? 'urgent' : intent === 'human_request' ? 'human_request' : 'complaint';

const toWestern = s => String(s ?? '').replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d)).trim();
const b = raw.booking || {};
const booking = { name: String(b.name ?? '').trim(), phone: toWestern(b.phone), service: String(b.service ?? '').trim(),
  date: toWestern(b.date), time: toWestern(b.time) };

return [{ json: {
  ...ctx, intent, language, sentiment, urgency, needs_human, route, ticket_type, booking,
  summary: String(raw.summary || ctx.text).slice(0, 200),
  search_query: String(raw.search_query || ctx.text).slice(0, 300),
  ai_source: $json.__fallback ? 'keyword_fallback' : 'llm',
  validation_notes: notes.join('; '),
}}];

const docs = $input.all().map(i => i.json).filter(d => d.document?.pageContent);
const context = docs.map((d, i) => `[${i + 1}] ${d.document.pageContent.trim()}`).join('\n\n');
return [{ json: { kb_found: docs.length > 0, kb_context: context, chunk_count: docs.length,
  top_score: Number(docs[0]?.score ?? 0).toFixed(3) } }];

