// AI output validation for free text: strip formatting, cap length, never send an empty reply.
const ai = $('Validate AI Output').first().json;
let reply = String($json.text ?? '').trim();
reply = reply.replace(/<think>[\s\S]*?<\/think>/g, '').replace(/\*\*(.*?)\*\*/g, '$1').replace(/^#+\s*/gm, '').replace(/^\s*[-*]\s+/gm, '• ').trim();
const valid = reply.length >= 2;
if (!valid) reply = ai.language === 'ar'
  ? 'معلش، مش قادر أرد على السؤال ده دلوقتي. ممكن تكلمنا على 02 3333 4455 أو أحولك لفريق العيادة.'
  : "Sorry, I can't answer that right now. You can call us on 02 3333 4455 or I can connect you with our team.";
if (reply.length > 900) reply = reply.slice(0, 880).replace(/\s+\S*$/, '') + '…';
return [{ json: { reply, answer_valid: valid } }];

// Business validation the AI must not be trusted with: phone format, opening hours, closed days, the past.
const cfg = $('Get Config').first().json;
const ai = $('Validate AI Output').first().json;
const b = ai.booking || {};
const ar = ai.language === 'ar';
const tz = cfg.TIMEZONE;
const now = DateTime.now().setZone(tz);

let phone = String(b.phone || ai.stored_phone || '').replace(/[^\d+]/g, '');
if (phone.startsWith('+20')) phone = '0' + phone.slice(3);
else if (phone.startsWith('0020')) phone = '0' + phone.slice(4);
else if (phone.startsWith('20') && phone.length === 12) phone = '0' + phone.slice(2);
const name = (b.name || ai.stored_name || ai.customer_name || '').trim();
const service = (b.service || 'Consultation').trim();

const missing = [];
if (!b.date) missing.push('date');
if (!b.time) missing.push('time');
if (!phone) missing.push('phone');
if (!name) missing.push('name');

const problems = [];
if (phone && !/^01[0125]\d{8}$/.test(phone)) problems.push('phone');
let slot = null;
if (b.date && b.time) {
  slot = DateTime.fromISO(`${b.date}T${b.time}`, { zone: tz });
  if (!slot.isValid) problems.push('format');
  else {
    const open = slot.set({ hour: Number(cfg.OPEN_HOUR), minute: 0 });
    const last = DateTime.fromISO(`${b.date}T${cfg.LAST_SLOT}`, { zone: tz });
    if (slot < now.plus({ minutes: 30 })) problems.push('past');
    else if (slot > now.plus({ days: Number(cfg.MAX_DAYS_AHEAD) })) problems.push('too_far');
    if (String(cfg.CLOSED_WEEKDAYS).split(',').map(Number).includes(slot.weekday)) problems.push('closed_day');
    else if (slot < open || slot > last) problems.push('hours');
    if (slot.minute % Number(cfg.SLOT_MINUTES) !== 0) problems.push('grid');
  }
}

const L = {
  phone: ["That mobile number doesn't look right. Please send an 11-digit Egyptian mobile number starting with 010, 011, 012 or 015.", 'رقم الموبايل مش مظبوط. من فضلك ابعت رقم مصري 11 رقم بيبدأ بـ 010 أو 011 أو 012 أو 015.'],
  format: ["I couldn't understand the date or time. Please write it like 'Sunday 3 Nov at 5:30 pm'.", 'مقدرتش أفهم التاريخ أو الوقت. اكتبه كده مثلًا: الأحد 3 نوفمبر الساعة 5:30 مساءً.'],
  past: ['That time has already passed or is too soon. Please choose a later time.', 'الوقت ده فات أو قريب جدًا. من فضلك اختار وقت بعد كده.'],
  too_far: [`We book up to ${cfg.MAX_DAYS_AHEAD} days ahead. Please choose an earlier date.`, `بنحجز لحد ${cfg.MAX_DAYS_AHEAD} يوم قدام بس. اختار تاريخ أقرب.`],
  closed_day: ["We're closed on Fridays. We're open Saturday to Thursday, 10 AM to 10 PM.", 'العيادة مقفولة يوم الجمعة. مواعيدنا من السبت للخميس من 10 الصبح لـ 10 بالليل.'],
  hours: [`Appointments run from 10:00 AM until the last slot at ${cfg.LAST_SLOT}.`, `المواعيد من 10 الصبح لحد آخر ميعاد الساعة ${cfg.LAST_SLOT}.`],
  grid: ['Appointments start on the hour or half hour, for example 5:00 or 5:30.', 'المواعيد بتبدأ على الساعة أو النص، زي 5:00 أو 5:30.'],
};
const M = { date: ['preferred date', 'التاريخ المناسب'], time: ['preferred time', 'الوقت المناسب'],
  phone: ['mobile number', 'رقم الموبايل'], name: ['full name', 'الاسم بالكامل'] };
const i = ar ? 1 : 0;
const lines = problems.map(p => L[p][i]);
const ask = missing.filter(m => !(m === 'phone' && problems.includes('phone')));
if (ask.length) lines.push(ar
  ? `علشان أحجزلك محتاج: ${ask.map(m => M[m][1]).join('، ')}.`
  : `To book, I just need your ${ask.map(m => M[m][0]).join(', ')}.`);

const status = problems.length ? 'invalid' : missing.length ? 'incomplete' : 'ready';
return [{ json: {
  booking_status: status, reply: lines.join('\n'), name, phone, service,
  date: slot?.isValid ? slot.toISODate() : '', time: slot?.isValid ? slot.toFormat('HH:mm') : '',
  slot_label: slot?.isValid ? slot.setLocale(ar ? 'ar-EG' : 'en-GB').toFormat('cccc d LLLL, h:mm a') : '',
}}];

// Double-booking protection: only confirmed appointments block a slot.
const cfg = $('Get Config').first().json;
const req = $('Validate Booking').first().json;
const ar = $('Validate AI Output').first().json.language === 'ar';
const tz = cfg.TIMEZONE;
const taken = new Set($input.all().map(i => i.json)
  .filter(r => String(r.date) === req.date && r.status === 'confirmed').map(r => String(r.time)));
if (!taken.has(req.time)) return [{ json: { slot_free: true } }];
const now = DateTime.now().setZone(tz);
const last = DateTime.fromISO(`${req.date}T${cfg.LAST_SLOT}`, { zone: tz });
const wanted = DateTime.fromISO(`${req.date}T${req.time}`, { zone: tz });
const free = [];
for (let t = DateTime.fromISO(req.date, { zone: tz }).set({ hour: Number(cfg.OPEN_HOUR) }); t <= last; t = t.plus({ minutes: Number(cfg.SLOT_MINUTES) }))
  if (t > now.plus({ minutes: 30 }) && !taken.has(t.toFormat('HH:mm'))) free.push(t);
const options = free.sort((a, b) => Math.abs(a - wanted) - Math.abs(b - wanted)).slice(0, 3).sort((a, b) => a - b).map(t => t.toFormat('h:mm a'));
const reply = options.length
  ? (ar ? `للأسف ميعاد ${req.time} محجوز. المتاح في نفس اليوم: ${options.join('، ')}. تحب أي ميعاد؟` : `Sorry, ${req.slot_label} is already booked. Free times that day: ${options.join(', ')}. Which one works for you?`)
  : (ar ? 'للأسف اليوم ده محجوز بالكامل. تحب تختار يوم تاني؟' : 'Sorry, that day is fully booked. Would you like another day?');
return [{ json: { slot_free: false, booking_status: 'slot_taken', reply, alternatives: options } }];

const ai = $('Validate AI Output').first().json;
const b = $('Validate Booking').first().json;
const rand = Math.random().toString(36).slice(2, 6).toUpperCase();
return [{ json: {
  appointment_id: `A-${b.date.replace(/-/g, '').slice(2)}-${rand}`,
  customer_id: ai.customer_id, channel: ai.channel, name: b.name, phone: b.phone, service: b.service,
  date: b.date, time: b.time, status: ai.channel === 'test' ? 'test' : 'confirmed',
  created_at: $now.toISO(), notes: ai.summary,
}}];

const a = $('Prepare Appointment').first().json;
const b = $('Validate Booking').first().json;
const ar = $('Validate AI Output').first().json.language === 'ar';
const reply = ar
  ? `✅ تم الحجز يا ${a.name}!
📅 ${b.slot_label}
🦷 ${a.service}
📍 27 شارع مصدق، الدقي، الدور التاني
رقم الحجز: ${a.appointment_id}
ياريت تيجي قبل الميعاد بـ 10 دقايق. لو حبيت تلغي أو تغير ابعتلنا قبلها بـ 12 ساعة.`
  : `✅ You're booked, ${a.name}!
📅 ${b.slot_label}
🦷 ${a.service}
📍 27 Mosadak St, 2nd floor, Dokki
Booking ID: ${a.appointment_id}
Please arrive 10 minutes early. To cancel or change, message us at least 12 hours before.`;
return [{ json: { reply, booking_status: 'confirmed', appointment_id: a.appointment_id } }];

const cfg = $('Get Config').first().json;
const ai = $('Validate AI Output').first().json;
const now = DateTime.now().setZone(cfg.TIMEZONE);
const rand = Math.random().toString(36).slice(2, 6).toUpperCase();
const handoff = ai.route === 'handoff';
const priority = ai.intent === 'urgent' ? 'urgent' : (handoff ? 'high' : 'normal');
const slaMin = Number({ urgent: cfg.SLA_URGENT_MIN, high: cfg.SLA_HIGH_MIN, normal: cfg.SLA_NORMAL_MIN }[priority]);
return [{ json: {
  ticket_id: `T-${now.toFormat('yyMMdd')}-${rand}`,
  customer_id: ai.customer_id, channel: ai.channel, channel_user_id: ai.channel_user_id,
  customer_name: ai.stored_name || ai.customer_name || 'Unknown', language: ai.language,
  type: handoff ? ai.ticket_type : 'complaint', reason: ai.intent, urgency: ai.urgency, sentiment: ai.sentiment,
  priority, status: 'open', summary: ai.summary, last_customer_message: ai.text.slice(0, 500),
  assigned_to: '', staff_message_id: '', created_at: now.toISO(), taken_at: '', first_response_at: '',
  resolved_at: '', sla_due_at: now.plus({ minutes: slaMin }).toISO(), escalation_count: 0, last_escalated_at: '',
}}];

const t = $('Create Ticket').first().json;
const ai = $('Validate AI Output').first().json;
const ar = ai.language === 'ar';
const id = t.ticket_id;
let reply;
if (t.type === 'urgent') reply = ar
  ? `سلامتك! 🙏 بلّغت فريق الأطباء وحد هيتواصل معاك في أقرب وقت (رقم الطلب ${id}).\nلو في نزيف شديد مش بيقف أو ورم بيأثر على التنفس أو البلع، اتصل بالإسعاف 123 أو روح أقرب طوارئ فورًا.`
  : `I'm sorry you're dealing with this. 🙏 I've alerted our dental team and someone will contact you shortly (ticket ${id}).\nIf you have heavy bleeding that won't stop, or swelling that affects breathing or swallowing, call 123 or go to the nearest emergency department now.`;
else if (t.type === 'human_request') reply = ar
  ? `أكيد، حولت رسالتك لفريق العيادة وحد من الموظفين هيرد عليك هنا قريب (رقم الطلب ${id}).`
  : `Sure, I've passed your message to our team and a staff member will reply here shortly (ticket ${id}).`;
else if (ai.route === 'handoff') reply = ar
  ? `إحنا آسفين جدًا على اللي حصل. صعّدت الموضوع لمدير العيادة وحد من الفريق هيرد عليك هنا قريب. رقم الشكوى ${id}.`
  : `I'm really sorry about this experience. I've escalated it to our clinic manager, and a team member will reply to you here shortly. Your ticket number is ${id}.`;
else reply = ar
  ? `شكرًا إنك قلتلنا، وآسفين على اللي حصل. سجلت شكوتك برقم ${id} ومدير العيادة هيرد عليك خلال 24 ساعة.`
  : `Thank you for telling us, and I'm sorry about this. I've logged your complaint as ticket ${id}, and our clinic manager will reply within 24 hours.`;
return [{ json: { reply, ticket_id: id } }];

